// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and XPAYR_WEBHOOK_SECRET in the n8n environment.
const crypto = require('crypto');
const secret = String($env.XPAYR_WEBHOOK_SECRET || '');
if (secret === '') {
  // Fail closed: never accept webhooks when the signing secret is missing.
  throw new Error('XPAYR_WEBHOOK_SECRET is not configured');
}
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const header = String(($json.headers || {})['x-xpayr-signature'] || '').trim().toLowerCase().replace(/^sha256=/, '');
let valid = false;
if (/^[a-f0-9]{64}$/.test(header)) {
  const expected = crypto.createHmac('sha256', secret).update(raw).digest();
  valid = crypto.timingSafeEqual(expected, Buffer.from(header, 'hex'));
}
let event = {};
if (valid) {
  try { event = JSON.parse(raw.toString('utf8')); } catch (e) { valid = false; }
}
const data = (event && event.data) || {};
const paymentId = String(data.payment_id || data.id || event.session_id || '');
if (!/^[A-Za-z0-9_-]{6,128}$/.test(paymentId)) valid = false;
return { json: { valid, event_id: event.id || null, event_type: event.type || event.event || null, payment_id: valid ? paymentId : null } };

// Fulfil only when XPayr itself reports the payment as settled; never trust the webhook body alone.
const status = String($json.status || '').toLowerCase();
const settled = status === 'completed' || status === 'underpaid_accepted';
return { json: { payment_id: $('Verify X-XPayr-Signature (fail closed)').item.json.payment_id, status, fulfil: settled } };
